'use strict';require('dotenv').config();const{transaction,pool}=require('../src/db/pool');const{hashPassword}=require('../src/security/password');
const[name,slug,email,password]=process.argv.slice(2);if(!name||!slug||!email||!password){console.error('Usage: node scripts/bootstrap-school.js "School Name" school-slug admin@example.com "StrongPassword"');process.exit(1);}
(async()=>{await transaction(async client=>{const school=(await client.query('INSERT INTO schools(name,slug) VALUES($1,$2) RETURNING id',[name,slug])).rows[0],hash=await hashPassword(password);await client.query(`INSERT INTO users(school_id,email,role,status,password_hash,must_change_password) VALUES($1,$2,'IT_ADMIN','ACTIVE',$3,true)`,[school.id,email.toLowerCase(),hash]);await client.query(`INSERT INTO grading_rules(school_id,grade,minimum_score,maximum_score,remark,sort_order,status) VALUES ($1,'A',70,100,'Excellent',1,'ACTIVE'),($1,'B',60,69,'Very Good',2,'ACTIVE'),($1,'C',50,59,'Good',3,'ACTIVE'),($1,'D',45,49,'Pass',4,'ACTIVE'),($1,'E',40,44,'Fair',5,'ACTIVE'),($1,'F',0,39,'Needs Improvement',6,'ACTIVE')`,[school.id]);console.log(`Created school ${school.id}; administrator must change password at first login.`);});})().catch(e=>{console.error(e.message);process.exitCode=1;}).finally(()=>pool.end());
